--- Creating the Primary Table for Neighborhood data

CREATE OR REPLACE TABLE `nyc_analysis.ref_neighborhoods` (
    neighborhood_id INT64,
    name STRING,
    borough_id INT64
    -- FOREIGN KEY (borough_id) REFERENCES boroughs(borough_id)
);

